<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowLeft, ArrowDown, ArrowUp, Pencil, Plus, Trash2 } from 'lucide-vue-next'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue';import WorkspaceTabs from '../components/WorkspaceTabs.vue';import StatusBadge from '../components/StatusBadge.vue';import JalaliDatePicker from '../components/JalaliDatePicker.vue';import OrderItemConfigurator from '../components/OrderItemConfigurator.vue';import DocumentMetadataPanel from '../components/DocumentMetadataPanel.vue';import type { QuoteRecord, QuotePayload } from '../api/quotes';import { quotesApi } from '../api/quotes';import type { OrderItemPayload } from '../api/orders';import type { CurrencyUnit } from '../utils/currency';import { formatMoney,formatMoneyInput,parseMoneyInput } from '../utils/currency';import { formatDateTime } from '../utils/date'
import SelectField from '../components/SelectField.vue'
const props=defineProps<{quote:QuoteRecord;currencyUnit:CurrencyUnit;customers:any[];services:any[];materials:any[]}>();const emit=defineEmits<{back:[];notify:[message:string];saved:[quote:QuoteRecord];converted:[orderId:string]}>();const tab=ref('Overview');const customerId=ref('');const expiryDate=ref<string|null>(null);const notes=ref('');const discountText=ref('');const editorOpen=ref(false);const editingItem=ref<any|null>(null);const saving=ref(false);const tabs=['Overview','Items','Files'];const customer=computed(()=>props.customers.find(c=>c.id===customerId.value));
watch(()=>props.quote,(q)=>{customerId.value=q.customerId||'';expiryDate.value=q.expiryDate;notes.value=q.notes;discountText.value=formatMoneyInput(q.discountRial,props.currencyUnit)},{immediate:true});function tone(v:string){return v==='Accepted'||v==='Converted'?'green':v==='Sent'?'blue':v==='Rejected'?'red':v==='Expired'?'amber':'slate'}function money(v:number){return formatMoney(v,props.currencyUnit)}function payload():QuotePayload{return{customerId:customerId.value,expiryDate:expiryDate.value,notes:notes.value,discountRial:parseMoneyInput(discountText.value,props.currencyUnit)||0}}
async function saveMetadata(){saving.value=true;try{emit('saved',await quotesApi.update(props.quote.id,payload()));emit('notify','Quote details saved')}catch(e){emit('notify',String(e))}finally{saving.value=false}}async function configured(input:OrderItemPayload){saving.value=true;try{const result=editingItem.value?await quotesApi.replaceItem(props.quote.id,editingItem.value.id,input):await quotesApi.addItem(props.quote.id,input);emit('saved',result);editorOpen.value=false;editingItem.value=null;emit('notify',editingItem.value?'Item replaced':'Item added')}catch(e){emit('notify',String(e))}finally{saving.value=false}}async function remove(item:any){try{emit('saved',await quotesApi.removeItem(props.quote.id,item.id));emit('notify','Item removed')}catch(e){emit('notify',String(e))}}async function move(item:any,delta:number){const items=[...props.quote.items].sort((a,b)=>a.position-b.position);const i=items.findIndex(x=>x.id===item.id);const n=i+delta;if(n<0||n>=items.length)return;[items[i],items[n]]=[items[n],items[i]];try{emit('saved',await quotesApi.reorderItems(props.quote.id,items.map(x=>x.id)))}catch(e){emit('notify',String(e))}}async function changeStatus(value:string){try{emit('saved',await quotesApi.status(props.quote.id,value));emit('notify','Quote status updated')}catch(err){emit('notify',String(err))}}async function discount(){try{const amount=parseMoneyInput(discountText.value,props.currencyUnit);if(amount===null)throw new Error('Enter a valid discount');emit('saved',await quotesApi.discount(props.quote.id,amount));emit('notify','Discount applied')}catch(e){emit('notify',String(e))}}async function convert(){if(props.quote.convertedOrderId)return;try{const result=await quotesApi.convert(props.quote.id);emit('saved',result);emit('converted',result.convertedOrderId);emit('notify','Quote converted to order')}catch(e){emit('notify',String(e))}}
</script>
<template><div><WorkspaceStickyStack :flush="true"><header><button class="btn btn-ghost" @click="emit('back')"><ArrowLeft :size="16"/>Quotes</button><div><p>Sales / Quote workspace</p><div><h1>{{ quote.quoteNumber }}</h1><StatusBadge :label="quote.status" :tone="tone(quote.status)"/></div><p>{{ quote.customerName||'Walk-in customer' }} · {{ quote.items.length }} line items</p></div><div><SelectField :model-value="quote.status" label="Status" :options="[{ label: 'Draft', value: 'Draft' }, { label: 'Sent', value: 'Sent' }, { label: 'Accepted', value: 'Accepted' }, { label: 'Rejected', value: 'Rejected' }, { label: 'Expired', value: 'Expired' }, { label: 'Converted', value: 'Converted' }]" @update:model-value="changeStatus" /><button class="btn btn-ghost" v-if="quote.status==='Accepted'&&!quote.convertedOrderId" :disabled="saving" @click="convert">Convert to order</button><button class="btn btn-ghost" :disabled="saving||quote.status!=='Draft'" @click="saveMetadata">Save quote</button></div></header><section><div><span>Customer</span><span>{{ customer?.name||quote.customerName||'Walk-in customer' }}</span><span>{{ customer?.phone||quote.customerPhone||'No contact details' }}</span></div><div><span>Created</span><span>{{ formatDateTime(quote.createdAt) }}</span><span>Jalali presentation</span></div><div><span>Expiry date</span><JalaliDatePicker v-model="expiryDate" placeholder="Set expiry date"/></div><div><span>Snapshot rule</span><span>Saved pricing</span><span>Reconfigure explicitly</span></div></section><WorkspaceTabs :tabs="tabs" :active-tab="tab" @change="tab=$event"/></WorkspaceStickyStack><section v-if="tab==='Overview'"><section><header><div><h2>Quote details</h2><p>Customer and commercial context</p></div></header><div><SelectField v-model="customerId" label="Customer" :options="[{ label: 'Walk-in customer', value: '' }, ...customers.filter((x:any)=>x.active||x.id===customerId).map((customer:any) => ({ label: customer.name, value: customer.id }))]" /><label class="form-control gap-1">Notes<textarea class="textarea textarea-bordered w-full min-w-0" v-model="notes" rows="5" placeholder="Quote notes"/></label></div><button class="btn btn-ghost" :disabled="saving||quote.status!=='Draft'" @click="saveMetadata">Save details</button></section><section><header><h2>Quote summary</h2></header><div><span>Subtotal<strong>{{ money(quote.subtotalRial) }}</strong></span><span>Discount<strong>{{ money(quote.discountRial) }}</strong></span><span>Total<strong>{{ money(quote.totalRial) }}</strong></span><span>Estimated cost<strong>{{ money(quote.estimatedCostRial) }}</strong></span></div><label class="form-control gap-1">Quote discount<input class="input input-bordered w-full min-w-0" :value="discountText" @input="discountText=($event.target as HTMLInputElement).value" @blur="discountText=formatMoneyInput(parseMoneyInput(discountText,props.currencyUnit)||0,props.currencyUnit)"/><button class="btn btn-ghost" :disabled="quote.status!=='Draft'" @click="discount">Apply</button></label><div v-if="quote.convertedOrderId">Linked order: {{ quote.convertedOrderId }}</div></section></section><section v-else-if="tab==='Items'"><div v-if="!editorOpen"><header><div><h2>Configured items</h2><p>Each item keeps its accepted service and pricing snapshot.</p></div><button class="btn btn-ghost" :disabled="quote.status!=='Draft'" @click="editorOpen=true"><Plus :size="15"/>Add service item</button></header><div v-if="!quote.items.length">No items yet. Add the first configured service.</div><div v-for="item in [...quote.items].sort((a,b)=>a.position-b.position)" :key="item.id"><div>{{ item.position+1 }}</div><div><strong>{{ item.serviceName }}</strong><span>{{ item.quantity }} {{ item.quantityUnit }}<template v-if="item.notes"> · {{ item.notes }}</template></span><small>Accepted snapshot · {{ item.resolvedParametersJson?JSON.parse(item.resolvedParametersJson).length:0 }} parameters</small></div><div><span>Cost {{ money(item.estimatedCostRial) }}</span><strong>{{ money(item.sellingPriceRial) }}</strong></div><div><button class="btn btn-ghost" @click="move(item,-1)"><ArrowUp :size="14"/></button><button class="btn btn-ghost" @click="move(item,1)"><ArrowDown :size="14"/></button><button class="btn btn-ghost" :disabled="quote.status!=='Draft'" @click="editingItem=item;editorOpen=true"><Pencil :size="14"/></button><button class="btn btn-ghost" :disabled="quote.status!=='Draft'" @click="remove(item)"><Trash2 :size="14"/></button></div></div></div><OrderItemConfigurator v-else :services="services" :materials="materials" :currency-unit="currencyUnit" document-label="quote" :initial="editingItem" @configured="configured" @cancel="editorOpen=false;editingItem=null"/></section><DocumentMetadataPanel v-else owner-type="quote" :owner-id="quote.id" :protected-context="quote.status !== 'Draft'" @notify="emit('notify',$event)"/></div></template>
